example.code:
{
  "editor.formatOnSave": true,
  "editor.defaultFormatter": "esbenp.prettier-vscode"
}

{
  "recommendations": ["esbenp.prettier-vscode", "dbaeumer.vscode-eslint"]
}

{
  "version": "2.0.0",
  "tasks": [
    { "label": "build", "type": "shell", "command": "npm run build" },
    { "label": "test", "type": "shell", "command": "npm test" }
  ]
}

{
  // .vscode/settings.json (COMMITTED - the team contract)
  "editor.tabSize": 4,
  "editor.formatOnSave": true,
  "editor.defaultFormatter": "esbenp.prettier-vscode",
  "python.defaultInterpreterPath": "${workspaceFolder}/.venv/bin/python"
}
// Personal theme/keys live in USER settings. Never here.

{
  // .vscode/extensions.json (COMMITTED - the team allowlist)
  "recommendations": ["dbaeumer.vscode-eslint", "ms-python.python"],
  "unwantedRecommendations": ["shady.theme-pack"]
}
// Each recommendation vetted: publisher, permissions, update policy.
// Versions pinned in the workspace docs; updates reviewed, not auto.

{
  "label": "build", "type": "shell", "command": "npm run build",
  "problemMatcher": "$tsc",
  "presentation": { "reveal": "silent", "panel": "dedicated" }
}
// Ctrl+Shift+B -> build runs -> errors parsed -> Problems panel lists them.
// Click: jumps to file:line. The 400-line scroll: retired.
